          ['루브릭 문장법', 8, '결과물 채점과 과정 관찰의 차이, 루브릭 단계를 "보이는 행동"으로 쓰는 법을 나쁜 예 · 좋은 예 2쌍으로 설명'],
          ['실습', 10, '관찰 체크리스트 5항목(수업 중 교사가 눈으로 체크할 수 있는 행동)과 루브릭 3단계 초안을 시트에 작성, AI에는 성취기준과 과제만 입력'],
          ['고쳐 쓰기', 7, '예시 답안 2건에 AI 피드백 초안을 받아 내 루브릭 용어 · 내 말투로 고치고, 바꾼 부분을 색으로 표시'],
          ['채점 맞춰 보기', 5, '짝이 내 루브릭으로 예시 답안 1건을 채점, 나와 다른 단계를 준 항목의 문장을 함께 다듬기']
